#!/usr/bin/env bash
set -eo pipefail
readonly SEQUENCE=184
readonly OUTPUT_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_stability_diagnosis_development_20260921_v1"
readonly SOURCE_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908_v3_aligned_rematch_20260916/workspace"
readonly RUNS_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908_v3_aligned_rematch_20260916/runs"
readonly PYTHON_BIN="/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python"
readonly JOB_NAME="kdpp_stab_d1"

echo "DIAG_SUBMIT_V1"
echo "sequence=$SEQUENCE"
echo "timestamp=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "host=$(hostname)"

if [[ -e "$OUTPUT_ROOT" ]]; then
  echo "REFUSING: output root already exists: $OUTPUT_ROOT" >&2
  exit 20
fi
if [[ ! -d "$SOURCE_ROOT" || ! -d "$RUNS_ROOT" || ! -x "$PYTHON_BIN" ]]; then
  echo "REFUSING: frozen source, runs root, or Python is absent" >&2
  exit 21
fi
if squeue -h -u "$USER" -n "$JOB_NAME" | grep -q .; then
  echo "REFUSING: a job with the unique diagnostic name already exists" >&2
  exit 22
fi
idle_nodes=$(sinfo -h -p hcpu48 -t idle -o '%D' | awk '{sum += $1} END {print sum + 0}')
if [[ "$idle_nodes" -lt 1 ]]; then
  echo "REFUSING: hcpu48 has no idle node at submission time" >&2
  exit 23
fi
echo "hcpu48_idle_nodes=$idle_nodes"

printf '%s  %s\n' \
  '934570d3c840e9d57b8fbddf3a018dc29e190cdd712fc9daaf442e383f74d843' "$SOURCE_ROOT/knet/dl/nn_kalman_clamp_5.py" \
  '3eb80fc1346a3e86170cac28fecad29951fe938193967e6a8cf6ae705edc22da' "$SOURCE_ROOT/src/global_hydrology/models/knet_native_hbvlite_full_state.py" \
  '770de40d8d472805515c00131c37f4852012be1e0a42b7a3aeb36689a192daa8' "$SOURCE_ROOT/src/global_hydrology/experiments/daily_camels_knet_per_basin_runner.py" \
  '2fd983a4af52ee02fd677e8ee51894d8208b836d6e9759b3ff2ac3a82c89ea69' "$SOURCE_ROOT/src/global_hydrology/experiments/daily_camels_ukf_knet_parity_runner.py" \
  '0d32d0f8dc656bdfbea81ba9f61eba0775ecc770d4466ff0442597d7c8d7a597' "$SOURCE_ROOT/src/global_hydrology/models/hbvlite_system_model.py" \
  'd7a04be86f19cddd8b9703e432fafb999a38215cb85de8983fe39a40bda0d6ea' "$SOURCE_ROOT/src/global_hydrology/models/differentiable_hbv_lite.py" | sha256sum --check --strict

readonly DATA_FILE="$SOURCE_ROOT/results/tukf06_full_diagonal_search_head_to_head_v1/selection_inputs/basin_02092500.npz"
if [[ ! -f "$DATA_FILE" || "$(stat -c '%s' "$DATA_FILE")" != '70808' ]]; then
  echo "REFUSING: development archive path or byte size changed" >&2
  exit 24
fi
printf '%s  %s\n' '453d57eab87b0d774d5895f143d51c40644f9b92fd8702ce646a6f4841378eb6' "$DATA_FILE" | sha256sum --check --strict

check_summary() {
  local seed="$1" epoch="$2" rel="$3" digest="$4"
  local run_id="DAILY_CAMELS_KNET_ALIGNED_REMATCH_V3_20260916_KNET_BASIN_02092500_SEED_${seed}"
  local summary="$RUNS_ROOT/$run_id/result_summary.json"
  [[ -f "$summary" ]] || { echo "REFUSING: result summary absent for seed $seed" >&2; exit 25; }
  grep -Fq "\"best_epoch\": $epoch" "$summary" || { echo "REFUSING: best epoch changed for seed $seed" >&2; exit 26; }
  grep -Fq "\"best_checkpoint\": \"$rel\"" "$summary" || { echo "REFUSING: checkpoint path changed for seed $seed" >&2; exit 27; }
  grep -Fq "\"best_checkpoint_sha256\": \"$digest\"" "$summary" || { echo "REFUSING: checkpoint digest registration changed for seed $seed" >&2; exit 28; }
  local checkpoint="$RUNS_ROOT/$run_id/$rel"
  [[ -f "$checkpoint" ]] || { echo "REFUSING: checkpoint absent for seed $seed" >&2; exit 29; }
  printf '%s  %s\n' "$digest" "$checkpoint" | sha256sum --check --strict
}
check_summary 20260824 151 'checkpoints/epoch_151.pt' 'dba62964dc897f282db80eddba93aa163ced1c248d60ec4f0ac6a7254d76b666'
check_summary 20260901 80 'checkpoints/epoch_080.pt' 'c8e4fb2baf47bb92324cd7760609d9e1a06ac934275ddf5b1c3a809219ffbe8c'
check_summary 20260908 178 'checkpoints/epoch_178.pt' 'f69b3068c08e14aa17495a618a7827f4218d608126624a65dfc7dab181a2a7ee'
check_summary 20260915 124 'checkpoints/epoch_124.pt' '465a5fe8cbae21beec06324e64127b36cd9eeadec68d285d547b03d4fbfd6dd5'
check_summary 20260922 134 'checkpoints/epoch_134.pt' 'ba99d913dad8365a607702684e190ec38d46085cc301d5bc84469897f73e87d7'

mkdir -p "$OUTPUT_ROOT/payload" "$OUTPUT_ROOT/logs" "$OUTPUT_ROOT/tmp"
printf '%s' '' | base64 --decode | gzip --decompress > "$OUTPUT_ROOT/payload/trace_development.py"
printf '%s' '' | base64 --decode | gzip --decompress > "$OUTPUT_ROOT/diagnosis_contract.json"
printf '%s' '' | base64 --decode | gzip --decompress > "$OUTPUT_ROOT/source_manifest.json"
chmod 0444 "$OUTPUT_ROOT/payload/trace_development.py" "$OUTPUT_ROOT/diagnosis_contract.json" "$OUTPUT_ROOT/source_manifest.json"
printf '%s  %s\n' \
  '9e2a5735e555cb63b2ab6bbeef277d825159f87a3ff860bc56e9f9be634fe36b' "$OUTPUT_ROOT/payload/trace_development.py" \
  'b422441e19d28449f685ebb65fb24a8d87064854151a9c710a7e8909982277dc' "$OUTPUT_ROOT/diagnosis_contract.json" \
  'cd98c5b135abab830c682d779613fd12a01553a1a6b40280d9d68a6cf21639f0' "$OUTPUT_ROOT/source_manifest.json" | sha256sum --check --strict

readonly SLURM_SCRIPT="$OUTPUT_ROOT/payload/run.slurm"
cat > "$SLURM_SCRIPT" <<'SLURM_EOF'
#!/usr/bin/env bash
#SBATCH --job-name=kdpp_stab_d1
#SBATCH --partition=hcpu48
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=1
#SBATCH --time=01:00:00
#SBATCH --exclusive
#SBATCH --output=/data1/home/sunyiq/kalmannet_daily_camels_stability_diagnosis_development_20260921_v1/logs/slurm-%j.out
#SBATCH --error=/data1/home/sunyiq/kalmannet_daily_camels_stability_diagnosis_development_20260921_v1/logs/slurm-%j.err

set -eo pipefail
readonly OUTPUT_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_stability_diagnosis_development_20260921_v1"
readonly SOURCE_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908_v3_aligned_rematch_20260916/workspace"
readonly PYTHON_BIN="/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python"
export ATEN_CPU_CAPABILITY=default
export OMP_NUM_THREADS=1
export MKL_NUM_THREADS=1
export OPENBLAS_NUM_THREADS=1
export NUMEXPR_NUM_THREADS=1
export VECLIB_MAXIMUM_THREADS=1
export BLIS_NUM_THREADS=1
export PYTHONDONTWRITEBYTECODE=1
export PYTHONNOUSERSITE=1
export CUDA_VISIBLE_DEVICES=""
export TMP="$OUTPUT_ROOT/tmp"
export TEMP="$OUTPUT_ROOT/tmp"
export TMPDIR="$OUTPUT_ROOT/tmp"
export PYTHONPATH="$SOURCE_ROOT/src:$SOURCE_ROOT"
cd "$SOURCE_ROOT"
exec "$PYTHON_BIN" "$OUTPUT_ROOT/payload/trace_development.py" --contract "$OUTPUT_ROOT/diagnosis_contract.json"
SLURM_EOF
chmod 0555 "$SLURM_SCRIPT"
bash -n "$SLURM_SCRIPT"
sha256sum "$SLURM_SCRIPT" > "$OUTPUT_ROOT/slurm_script.sha256"

submit_output=$(sbatch "$SLURM_SCRIPT")
echo "$submit_output"
if [[ ! "$submit_output" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]; then
  echo "REFUSING: scheduler did not return a canonical job receipt" >&2
  exit 30
fi
job_id="${BASH_REMATCH[1]}"
submitted_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)
printf '{"schema_version":"daily_camels_stability_submission_receipt_v1","job_id":"%s","job_name":"%s","partition":"hcpu48","submitted_at_utc":"%s","retry_allowed":false}\n' "$job_id" "$JOB_NAME" "$submitted_at" > "$OUTPUT_ROOT/submission_receipt.json"
chmod 0444 "$OUTPUT_ROOT/submission_receipt.json" "$OUTPUT_ROOT/slurm_script.sha256"
echo "job_id=$job_id"
echo "output_root=$OUTPUT_ROOT"

